template.script:
(function () {
    var jobId = ;
    var token = "";
    var live = ;
    var note = document.getElementById("sa_geo_note");
    if (!live) { return; }
    if (!navigator.geolocation) {
        if (note) { note.textContent = "This phone cannot share its position."; }
        return;
    }
    // Reported at most every 20s. A delivery is minutes long, and
    // a fix per second would drain the battery it depends on.
    var last = 0;
    function send(pos) {
        var now = Date.now();
        if (now - last < 20000) { return; }
        last = now;
        var body = new FormData();
        body.append("token", token);
        body.append("lat", pos.coords.latitude);
        body.append("lng", pos.coords.longitude);
        body.append("acc", pos.coords.accuracy || 0);
        fetch("/wa/delivery/" + jobId + "/ping", {
            method: "POST", body: body
        }).then(function (r) { return r.json(); })
          .then(function (d) {
            if (d && d.stop && watch !== null) {
                navigator.geolocation.clearWatch(watch);
                watch = null;
            } else if (note) {
                note.textContent = "This page is sending your position to the customer while it stays open.";
            }
          }).catch(function () { /* a lost fix is not worth a popup */ });
    }
    function failed(err) {
        if (note) {
            note.textContent = err && err.code === 1
                ? "Location is off - the customer cannot follow you."
                : "Could not read your position.";
        }
    }
    var watch = navigator.geolocation.watchPosition(send, failed, {
        enableHighAccuracy: true, maximumAge: 15000, timeout: 20000
    });
})();
